function taskPersonName(id,actors){return actors.find(actor=>actor.id===id&&actor.kind==='human')?.name||t('notSet')}
function taskEventKindLabel(kind){return ({work_item_updated:t('workItemUpdated'),followers_changed:t('followersChanged'),assignment_changed:t('assignmentChanged'),stage_transition:t('stageTransition'),message:t('messageKind')})[kind]||kind.replaceAll('_',' ')}
function chatEventMarkup(event,actors){
  const author=taskEventAuthor(event,actors),own=event.author_type==='human'&&event.author_id===state.me.id;
  if(event.kind!=='message')return `<div class="chat-system-event"><span>${icon('activity')}${escapeHTML(author)} ${escapeHTML(taskEventKindLabel(event.kind))} · ${taskDate(event.created_at)}</span></div>`;
  const attachments=(event.attachments||[]).map(attachment=>attachmentMarkup(attachment)).join('');
  const text=taskEventText(event),onlyAttachment=text==='附件'||text==='Attachments';
  return `<article class="chat-message ${own?'own':''}"><span class="entry-avatar">${taskAvatar(author,'P')}</span><div class="chat-message-content"><div class="entry-head"><strong>${escapeHTML(author)}</strong><time>${taskDate(event.created_at)}</time></div>${onlyAttachment?'':`<div class="chat-bubble">${escapeHTML(text)}</div>`}${attachments?`<div class="chat-attachments">${attachments}</div>`:''}</div></article>`;
}

function formatFileSize(bytes=0){if(bytes<1024)return `${bytes} B`;if(bytes<1024*1024)return `${Math.round(bytes/1024)} KB`;return `${(bytes/1024/1024).toFixed(1)} MB`}
function isMarkdownAttachment(attachment){return attachment.mime==='text/markdown'||/\.md$/i.test(attachment.original_name||'')}
function attachmentMarkup(attachment){
  const url=`/api/attachments/${encodeURIComponent(attachment.id)}`,image=(attachment.mime||'').startsWith('image/');
  if(image)return `<figure class="attachment-image"><a href="${url}" target="_blank" rel="noopener"><img src="${url}" alt="${escapeHTML(attachment.original_name)}" loading="lazy"></a><figcaption>${icon('image')}${escapeHTML(attachment.original_name)} · ${formatFileSize(attachment.size)}</figcaption></figure>`;
  return `<div class="attachment-file"><span>${icon('file')}</span><span><strong>${escapeHTML(attachment.original_name)}</strong><small>${formatFileSize(attachment.size)}</small></span>${isMarkdownAttachment(attachment)?`<button class="text-action" type="button" data-preview-markdown="${attachment.id}">${t('preview')}</button>`:''}<a class="text-action" href="${url}" download>${t('download')}</a></div>${isMarkdownAttachment(attachment)?`<div class="markdown-attachment-preview" id="markdown-${attachment.id}" hidden></div>`:''}`;
}
function safeMarkdown(markdown=''){
  const escaped=escapeHTML(markdown).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener">$1</a>');
  return escaped.split(/\r?\n/).map(line=>{if(/^###\s/.test(line))return `<h4>${line.slice(4)}</h4>`;if(/^##\s/.test(line))return `<h3>${line.slice(3)}</h3>`;if(/^#\s/.test(line))return `<h2>${line.slice(2)}</h2>`;if(/^[-*]\s/.test(line))return `<li>${line.slice(2)}</li>`;return line?`<p>${line}</p>`:'<br>'}).join('');
}
function wireMarkdownPreviews(){document.querySelectorAll('[data-preview-markdown]').forEach(button=>button.onclick=async()=>{const target=$(`#markdown-${CSS.escape(button.dataset.previewMarkdown)}`);if(!target.hidden){target.hidden=true;button.textContent=t('preview');return}button.disabled=true;try{const response=await fetch(`/api/attachments/${encodeURIComponent(button.dataset.previewMarkdown)}`);if(!response.ok)throw new Error(response.statusText);target.innerHTML=safeMarkdown(await response.text());target.hidden=false;button.textContent=t('collapsePreview')}catch(error){toast(error.message)}finally{button.disabled=false}})}
function taskEvidenceMarkup(item){
  const groups=[[t('discussionRecords'),item.conclusions],[t('executionRecords'),item.executions],[t('acceptanceRecords'),item.acceptances]];
  return groups.filter(([,records])=>records?.length).map(([label,records])=>`<section class="task-record-group"><h3>${label}<span>${records.length}</span></h3>${records.map((record,index)=>`<details><summary>${label} ${index+1}<time>${taskDate(record.created_at||record.started_at||record.completed_at)}</time></summary><pre>${escapeHTML(JSON.stringify(record,null,2))}</pre></details>`).join('')}</section>`).join('');
}
function taskBlockForm(item){openDrawer(t('blocker'),`<form class="form" id="blockTaskForm">${area(t('blockReason'),'reason','',`required placeholder="${escapeHTML(t('blockReasonPlaceholder'))}"`)}<div class="form-error" hidden></div><button class="button danger" type="submit">${t('confirmBlock')}</button></form>`,()=>wireForm('#blockTaskForm',data=>api(`/api/work-items/${item.id}/block`,{method:'POST',body:JSON.stringify({reason:data.reason,expectedVersion:item.version})})))}

