  $('#workspace').innerHTML=`<div class="wechat-task"><header class="chat-header"><button class="back-link" id="back">${icon('chevron')}${t(state.page==='myQueue'?'myQueue':'queue')}</button><div class="chat-title"><div><span>${escapeHTML(item.id)} · ${t('version',{version:item.version})}</span><h1>${escapeHTML(item.title)}</h1></div><div class="chat-header-actions"><button class="button" id="manageFollowers">${icon('users')}${t('manageFollowers')}</button>${terminal?'':`<button class="button" id="changeAssignee">${t('changeExecutor')}</button><button class="button ${item.blocked_at?'':'danger'}" id="toggleBlock">${t(item.blocked_at?'clearBlocked':'blockTask')}</button><button class="button danger" id="abandonItem">${t('abandonItem')}</button><button class="button primary" id="primaryTaskAction" ${item.blocked_at?'disabled':''}>${t(item.stage==='todo'?'changeExecutor':'stageNext')}</button>`}</div></div><div class="chat-members"><span class="chat-member-label">${t('assignee')}</span><span class="task-avatar">${taskAvatar(assignee.name)}</span><strong>${escapeHTML(assignee.name)}</strong><i></i><span>${t('creator')} ${escapeHTML(creator)}</span><i></i><span>${t('followers')} ${followers.length}</span><span class="chat-stage">${badge(t(item.stage),'signal')}${badge(t(item.priority))}${item.blocked_at?badge(t('blocked'),'danger'):''}</span></div><div class="task-route-compact"><div><span>${t('routeProgress')}</span><strong>${progress}</strong></div><div class="phase-band" role="list">${phaseMarkup(item)}</div></div></header><main class="chat-canvas"><section class="chat-context"><div class="context-message"><span class="entry-avatar system-avatar">${icon('message')}</span><div><strong>${t('workItemContext')}</strong><p>${escapeHTML(item.description_markdown||t('noDescription'))}</p></div></div><details class="task-facts"><summary>${icon('list')}${t('taskData')}</summary><dl><div><dt>${t('targetBranch')}</dt><dd><code>${escapeHTML(item.target_branch)}</code></dd></div><div><dt>${t('discussionMode')}</dt><dd>${taskModeLabel(item.discussion_mode)}</dd></div><div><dt>${t('executionMode')}</dt><dd>${taskModeLabel(item.execution_mode)}</dd></div><div><dt>${t('acceptanceMode')}</dt><dd>${taskModeLabel(item.acceptance_mode)}</dd></div><div><dt>${t('updated')}</dt><dd>${taskDate(item.updated_at)}</dd></div><div><dt>${t('dependencies')}</dt><dd>${escapeHTML((item.dependencies||[]).join(', ')||t('none'))}</dd></div>${item.blocked_at?`<div class="blocked-fact"><dt>${t('blocker')}</dt><dd>${escapeHTML(item.blocked_reason||t('blocked'))} · ${taskDate(item.blocked_at)}</dd></div>`:''}</dl>${taskEvidenceMarkup(item)}</details><div class="criteria-message"><div class="criteria-head"><div><strong>${t('acceptanceCriteria')}</strong><small>${t('criteriaDuringWork')}</small></div>${terminal?'':`<button class="text-action" id="editCriteria">${icon('settings')}${t('editCriteria')}</button>`}</div>${criteria.length?`<ol>${criteria.map(line=>`<li><span>${icon('check')}</span><p>${escapeHTML(line.replace(/^[-*]\s*/,''))}</p></li>`).join('')}</ol>`:`<p>${t('noCriteria')}</p>`}</div></section><section class="chat-history">${(item.conversation||[]).map(event=>chatEventMarkup(event,actors)).join('')||`<p class="conversation-empty">${t('noEvents')}</p>`}</section></main><form class="chat-composer" id="chatComposer"><span class="entry-avatar">${taskAvatar(state.me.displayName)}</span><div class="composer-main"><div class="pending-attachments" id="pendingAttachments" hidden></div><textarea name="markdown" rows="1" placeholder="${t('conversationPlaceholder')}"></textarea></div><label class="attachment-button" title="${t('addAttachment')}">${icon('paperclip')}<input id="attachmentInput" type="file" multiple accept="image/*,.md,.markdown,.txt,.pdf,.zip,.json,.csv"></label><button class="button primary" type="submit">${icon('chevron')}${t('send')}</button></form></div>`;
