let renderAgents=async function(){
  if(!state.project)return renderQueue();
  const data=await api('/api/agents'),enabled=data.filter(agent=>agent.status==='active');
  const totalCapacity=enabled.reduce((sum,agent)=>sum+(agent.maxConcurrentTasks||1),0),running=enabled.reduce((sum,agent)=>sum+(agent.currentLoad||0),0),available=Math.max(0,totalCapacity-running);
  const rows=enabled.map(agent=>{const load=agent.currentLoad||0,capacity=agent.maxConcurrentTasks||1,usage=Math.min(100,Math.round(load/capacity*100)),stateKey=load>=capacity?'capacityFull':load>0?'capacityBusy':'capacityReady',stateClass=load>=capacity?'full':load>0?'busy':'ready';return `<button class="agent-ops-row" data-agent="${agent.id}"><span class="agent-ops-avatar">${icon('bot')}<i class="${stateClass}"></i></span><span class="agent-ops-identity"><strong>${escapeHTML(agent.name)}</strong><small>${escapeHTML(agent.purpose||t('noPurpose'))}</small><span>${t('localCodexCLI')}</span></span><span class="agent-ops-capacity"><span><small>${t(stateKey)}</small><strong>${load} / ${capacity}</strong></span><span class="agent-capacity-track"><i style="width:${usage}%"></i></span></span><span class="agent-ops-timeout"><small>${t('turnTimeoutMinutes')}</small><strong>${t('timeoutShort',{minutes:agent.turnTimeoutMinutes||120})}</strong></span><span class="agent-ops-arrow">${icon('chevron')}</span></button>`}).join('');
  $('#workspace').innerHTML=header(t('agents'),t('agentCapacityDeskNote'))+`<div class="content agent-ops-content"><section class="agent-ops-summary" aria-label="${escapeHTML(t('agentCapacityDesk'))}"><div class="agent-ops-summary-title"><span>${icon('activity')}</span><div><strong>${t('organizationCapacity')}</strong><small>${t('agentCapacityDesk')}</small></div></div><dl><div><dt>${t('enabledAgents')}</dt><dd>${enabled.length}</dd></div><div><dt>${t('runningTasks')}</dt><dd>${running}</dd></div><div><dt>${t('availableCapacity')}</dt><dd>${available}</dd></div></dl></section><section class="agent-ops-roster"><header><div><h2>${t('agentRoster')}</h2><p>${t('agentRosterNote')}</p></div><span>${enabled.length}</span></header>${rows?`<div class="agent-ops-list">${rows}</div>`:`<div class="agent-ops-empty">${icon('bot')}<strong>${t('noEnabledAgents')}</strong><p>${t('noEnabledAgentsAction')}</p></div>`}</section></div>`;
  document.querySelectorAll('[data-agent]').forEach(row=>row.onclick=()=>localAgentDrawer(data.find(agent=>agent.id===row.dataset.agent)));
};

function localDemoNotifications(){
  if(!['localhost','127.0.0.1','::1'].includes(location.hostname))return [];
  const task=state.items?.[0],taskID=task?.id||'',title=task?.title||'移动端任务队列适配';
  const now=Date.now(),read=new Set(JSON.parse(localStorage.pbDemoNotificationsRead||'[]'));
  return [
    ['assigned','你被指派了任务','需要你确认范围并补充实施方案',4],['mention','有人在讨论中提及你','@admin 请确认 API 兼容范围和回滚方案',18],['comment','任务有新评论','已上传交互截图与验收清单，请查看附件',42],['stage_changed','任务进入执行阶段','讨论结论已冻结，执行者可以开始处理',95],['acceptance_result','验收结果已更新','桌面端通过，窄屏下需要调整页签溢出',190],['blocked_changed','任务阻塞状态已更新','等待测试环境的仓库授权恢复',320]
  ].map(([kind,heading,body,minutes],index)=>({id:`demo-${index}`,project_id:state.project?.id,work_item_id:taskID,kind,title:`${heading} · ${t('localDemoData')}`,body,work_item_title:title,created_at:new Date(now-minutes*60000).toISOString(),read_at:read.has(`demo-${index}`)?new Date().toISOString():null,demo:true}));
}
renderMessages=async function(){
  const live=await api(`/api/notifications${state.project?`?projectId=${encodeURIComponent(state.project.id)}`:''}`),notifications=[...localDemoNotifications(),...live],unread=notifications.filter(item=>!item.read_at).length;
  $('#workspace').innerHTML=header(t('myMessages'),t('notificationCenter'),unread?`<button class="button" id="markAllRead">${icon('check')}${t('markAllRead')}</button>`:'')+`<div class="content notification-page"><div class="notification-summary"><strong>${unread}</strong><span>${t('unread')}</span>${localDemoNotifications().length?badge(t('localDemoData'),'signal'):''}</div><div class="notification-list">${notifications.map(item=>`<article class="notification-row ${item.read_at?'':'unread'}" data-notification="${item.id}" data-work-item="${item.work_item_id||''}" data-demo="${item.demo?'true':'false'}"><span class="notification-mark">${icon(item.kind==='comment'||item.kind==='mention'?'message':item.kind==='assigned'?'users':'activity')}</span><span class="notification-copy"><small>${escapeHTML(item.title)} · ${taskDate(item.created_at)}</small><strong>${escapeHTML(item.work_item_title||item.work_item_id||'ProjectBoard')}</strong><p>${escapeHTML(item.body||'')}</p></span>${item.read_at?'':`<i class="notification-unread" aria-label="${t('unread')}"></i>`}<button class="button notification-task-link" type="button" data-open-notification ${item.work_item_id?'':`disabled`}><span>${t('openWorkItem')}</span>${icon('chevron')}</button></article>`).join('')||`<div class="queue-empty"><strong>${t('noNotifications')}</strong><p>${t('noNotificationsNote')}</p></div>`}</div></div>`;
  const readAll=$('#markAllRead');if(readAll)readAll.onclick=async()=>{localStorage.pbDemoNotificationsRead=JSON.stringify(localDemoNotifications().map(item=>item.id));await api('/api/notifications/read-all',{method:'POST',body:'{}'});renderMessages()};
  document.querySelectorAll('[data-open-notification]').forEach(button=>button.onclick=async()=>{const row=button.closest('[data-notification]');if(row.dataset.demo==='true'){const ids=new Set(JSON.parse(localStorage.pbDemoNotificationsRead||'[]'));ids.add(row.dataset.notification);localStorage.pbDemoNotificationsRead=JSON.stringify([...ids])}else await api(`/api/notifications/${row.dataset.notification}/read`,{method:'POST',body:'{}'});state.page='queue';state.task=row.dataset.workItem;renderShell()});
};

