  const records=(item.conclusions?.length||0)+(item.executions?.length||0)+(item.acceptances?.length||0),evidence=[[t('taskDescription'),Boolean(item.description_markdown)],[t('acceptanceCriteria'),Boolean(item.acceptance_criteria_markdown)],[t('executionRecords'),records>0]];
  openDrawer(t('advanceStage'),`<form class="form stage-change-form" id="stageChangeForm"><div class="stage-change-grid"><div class="stage-current-card"><span>${t('currentStage')}</span><strong>${t(item.stage)}</strong></div><i>${icon('chevron')}</i><div class="stage-target-field"><span class="stage-field-label" id="targetStageLabel">${t('targetStage')}</span><div class="stage-select" id="targetStagePicker"><input type="hidden" name="targetStage" value="${suggested}"><button class="stage-select-trigger" id="targetStageTrigger" type="button" aria-haspopup="listbox" aria-expanded="false" aria-labelledby="targetStageLabel targetStageValue"><span id="targetStageValue">${t(suggested)}</span>${icon('chevron')}</button><div class="stage-select-menu" role="listbox" aria-labelledby="targetStageLabel" hidden>${options}</div></div><small>${t('changeStageHint')}</small></div></div><section class="task-config-section"><h3>${t('stageEvidence')}</h3><p class="task-section-note">${t('stageEvidenceHint')}</p><div class="stage-evidence-list">${evidence.map(([label,complete])=>`<div class="${complete?'complete':''}">${icon('check')}<span>${label}</span></div>`).join('')}</div></section>${area(t('changeStageNote'),'noteMarkdown','',`placeholder="${escapeHTML(t('changeStageHint'))}"`)}<div class="form-error" hidden></div><button class="button primary" type="submit" id="confirmStageChange"></button></form>`,()=>{const form=$('#stageChangeForm'),picker=$('#targetStagePicker'),trigger=$('#targetStageTrigger'),menu=$('.stage-select-menu',picker),input=$('input[name=targetStage]',picker),value=$('#targetStageValue'),button=$('#confirmStageChange'),optionButtons=[...picker.querySelectorAll('[data-stage-option]')];const update=stage=>{input.value=stage;value.textContent=t(stage);button.textContent=t('switchToStage',{stage:t(stage)});optionButtons.forEach(option=>option.setAttribute('aria-selected',String(option.dataset.stageOption===stage)))};const setOpen=open=>{menu.hidden=!open;trigger.setAttribute('aria-expanded',String(open));picker.classList.toggle('open',open);if(open)(optionButtons.find(option=>option.dataset.stageOption===input.value&&!option.disabled)||optionButtons.find(option=>!option.disabled))?.focus()};trigger.onclick=()=>setOpen(menu.hidden);optionButtons.forEach(option=>option.onclick=()=>{update(option.dataset.stageOption);setOpen(false);trigger.focus()});picker.onkeydown=event=>{const enabled=optionButtons.filter(option=>!option.disabled),active=enabled.indexOf(document.activeElement);if(event.key==='Escape'){setOpen(false);trigger.focus();event.preventDefault()}else if(event.key==='ArrowDown'||event.key==='ArrowUp'){if(menu.hidden){setOpen(true)}else{enabled[(active+(event.key==='ArrowDown'?1:-1)+enabled.length)%enabled.length]?.focus()}event.preventDefault()}else if(event.key==='Home'&&!menu.hidden){enabled[0]?.focus();event.preventDefault()}else if(event.key==='End'&&!menu.hidden){enabled.at(-1)?.focus();event.preventDefault()}};picker.addEventListener('focusout',event=>{if(!picker.contains(event.relatedTarget))setOpen(false)});update(suggested);form.onsubmit=async event=>{event.preventDefault();button.disabled=true;try{await api(`/api/work-items/${item.id}/stage`,{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(form)),expectedVersion:item.version})});closeDrawer();toast(t('stageChangedToast',{stage:t(input.value)}));await renderTask()}catch(error){$('.form-error',form).textContent=error.message;$('.form-error',form).hidden=false;button.disabled=false}}})
