let renderTask=async function(){
  const [item,actors]=await Promise.all([api(`/api/work-items/${state.task}`),loadTaskActors()]),assignee=taskAssignee(item,actors),terminal=['completed','order_closed','abandoned'].includes(item.stage),followers=item.follower_ids||[],creator=taskPersonName(item.created_by_user_id,actors),criteria=(item.acceptance_criteria_markdown||'').split(/\r?\n/).filter(line=>line.trim());
  const attachmentByEntry=new Map();(item.attachments||[]).forEach(attachment=>{if(!attachment.entry_id)return;const list=attachmentByEntry.get(attachment.entry_id)||[];list.push(attachment);attachmentByEntry.set(attachment.entry_id,list)});(item.conversation||[]).forEach(event=>event.attachments=attachmentByEntry.get(event.id)||[]);
  const policyValue=key=>t(state.project?.[key]?'allowed':'notAllowed');
  const actions=`<button class="button" id="configureTask" ${terminal?'disabled':''}>${icon('sliders')}${t('configure')}</button>${terminal?'':`<button class="button primary" id="advanceTaskStage">${t('advanceStage')}</button>`}`;
  $('#workspace').innerHTML=`<header class="page-head task-detail-page-head"><button class="back task-detail-back" id="taskQueueBack" type="button">${icon('chevron')}${t('queue')}</button><div class="page-title"><div><h1>${escapeHTML(item.title)}</h1><p>${escapeHTML(item.id)} · ${t(item.stage)} · ${t('assignee')} ${escapeHTML(assignee.name)} · ${t('creator')} ${escapeHTML(creator)} · ${t('followers')} ${followers.length}</p></div><div class="page-actions">${actions}</div></div><div class="task-workflow-scroll"><div class="task-workflow-track" role="list" aria-label="${t('routeProgress')}">${phaseMarkup(item)}</div></div></header><div class="content task-detail-page-content"><div class="task-detail-grid"><section class="task-conversation"><div class="task-thread"><article class="task-description-entry"><span class="entry-avatar">${taskAvatar(creator)}</span><div><header><strong>${escapeHTML(creator)}</strong><span>${taskDate(item.created_at||item.updated_at)}</span></header><p>${escapeHTML(item.description_markdown||t('noDescription'))}</p></div></article><div class="task-timeline">${(item.conversation||[]).map(event=>chatEventMarkup(event,actors)).join('')||`<p class="conversation-empty">${t('noEvents')}</p>`}</div></div><form class="task-composer" id="chatComposer"><div class="task-composer-box"><div class="pending-attachments" id="pendingAttachments" hidden></div><textarea name="markdown" rows="2" aria-label="${t('sendMessage')}" placeholder="${t('taskConversationPlaceholder')}"></textarea><div class="task-composer-tools"><label class="tool-button" title="${t('addAttachment')}">${icon('paperclip')}<input id="attachmentInput" type="file" multiple accept="image/*,.md,.markdown,.txt,.pdf,.zip,.json,.csv"></label><button class="tool-button" type="button" id="mentionTaskMember" aria-label="@">@</button><span>${t('taskComposerHint')}</span><button class="task-composer-send" type="submit" aria-label="${t('send')}">${icon('chevron')}</button></div></div></form></section><aside class="task-inspector"><h2>${t('executionContext')}</h2><dl><div><dt>${t('assignee')}</dt><dd>${escapeHTML(assignee.name)}</dd></div><div><dt>${t('targetBranch')}</dt><dd><code>${escapeHTML(item.target_branch)}</code></dd></div><div><dt>${t('agentExecution')}</dt><dd>${policyValue('allowAgentExecution')}</dd></div><div><dt>${t('automaticClose')}</dt><dd>${policyValue('allowAgentAutoClose')}</dd></div><div><dt>${t('subtasks')}</dt><dd>${policyValue('allowSubtasks')}</dd></div></dl><section><h3>${t('acceptanceCriteria')}</h3>${criteria.length?`<ul>${criteria.map(line=>`<li>${icon('check')}<span>${escapeHTML(line.replace(/^[-*]\s*/,''))}</span></li>`).join('')}</ul>`:`<p>${t('noCriteria')}</p>`}</section></aside></div></div>`;
  $('#taskQueueBack').onclick=()=>{state.task=null;renderQueue()};const configure=$('#configureTask');if(configure)configure.onclick=()=>taskConfigurationForm(item,actors);const advance=$('#advanceTaskStage');if(advance)advance.onclick=()=>stageForm(item);wireTaskComposer(item);harmonizePageStructure();
};

function projectPolicySwitch(name,label,note,checked){return `<label class="project-policy-row"><span><strong>${t(label)}</strong><small>${t(note)}</small></span><input type="checkbox" name="${name}" ${checked?'checked':''}><i aria-hidden="true"></i></label>`}
function projectPromptDrawer(project){let prompts=[...(project.agentPrompts||[])];openDrawer(t('agentCommonPrompts'),`<form class="form" id="projectPromptForm"><p class="drawer-note">${t('agentCommonPromptsNote')}</p><div class="project-prompt-list" id="projectPromptList"></div><div class="prompt-entry"><label class="field"><span>${t('addPrompt')}</span><textarea id="projectPromptInput" placeholder="${t('promptPlaceholder')}"></textarea></label><button class="button" type="button" id="addProjectPrompt">${icon('plus')}${t('addPrompt')}</button></div><div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form>`,()=>{const list=$('#projectPromptList'),input=$('#projectPromptInput'),paint=()=>{list.innerHTML=prompts.map((prompt,index)=>`<div><span>${escapeHTML(prompt)}</span><button type="button" data-prompt-index="${index}" aria-label="${t('removeFollower')}">${icon('x')}</button></div>`).join('')||`<small>${t('notSet')}</small>`;list.querySelectorAll('[data-prompt-index]').forEach(button=>button.onclick=()=>{prompts.splice(Number(button.dataset.promptIndex),1);paint()})};paint();$('#addProjectPrompt').onclick=()=>{const value=input.value.trim();if(value){prompts.push(value);input.value='';paint()}};$('#projectPromptForm').onsubmit=async event=>{event.preventDefault();const button=$('button[type=submit]',event.currentTarget);button.disabled=true;try{await api(`/api/projects/${project.id}`,{method:'PATCH',body:JSON.stringify({agentPrompts:prompts})});await loadProjects();closeDrawer();renderProjectSettingsPage()}catch(error){$('.form-error',event.currentTarget).textContent=error.message;$('.form-error',event.currentTarget).hidden=false;button.disabled=false}}})}
function confirmProjectRemoval(kind,entity){openDrawer(t('removeFromProject'),`<form class="form" id="projectRemovalForm"><p class="drawer-note">${escapeHTML(entity.name||entity.displayName)} · ${t('removeFromProject')}</p><p>${t(kind==='agent'?'agentDisabledNote':'memberRoleNote')}</p><div class="form-error" hidden></div><button class="button danger" type="submit">${t('confirmRemove')}</button></form>`,()=>{$('#projectRemovalForm').onsubmit=async event=>{event.preventDefault();const button=$('button[type=submit]',event.currentTarget);button.disabled=true;try{const path=kind==='agent'?`agents/${entity.id}`:`members/${entity.id}`;await api(`/api/projects/${state.project.id}/${path}`,{method:'DELETE',body:'{}'});closeDrawer();renderProjectSettingsPage()}catch(error){$('.form-error',event.currentTarget).textContent=error.message;$('.form-error',event.currentTarget).hidden=false;button.disabled=false}}})}

function logicalDeleteDrawer(kind,entity){const isAgent=kind==='agent',name=entity.name||entity.displayName,title=t(isAgent?'deleteAgent':'deleteUser'),note=t(isAgent?'deleteAgentNote':'deleteUserNote');openDrawer(title,`<form class="form logical-delete-form" id="logicalDeleteForm"><section class="logical-delete-summary"><span class="logical-delete-mark">${icon(isAgent?'bot':'user')}</span><div><span class="eyebrow">${title}</span><h3>${escapeHTML(name)}</h3><p>${note}</p></div></section><div class="form-error" hidden></div><button class="button danger logical-delete-submit" type="submit">${icon('trash')}${t(isAgent?'confirmDeleteAgent':'confirmDeleteUser')}</button></form>`,()=>{$('#logicalDeleteForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{await api(`/api/${isAgent?'agents':'users'}/${entity.id}`,{method:'DELETE',body:'{}'});closeDrawer();toast(t(isAgent?'agentDeleted':'userDeleted'));await renderSettingsHub()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}})}

