function settingsCardHead(title,note,action=''){return `<header class="settings-card-head"><div><h2>${title}</h2>${note?`<p>${note}</p>`:''}</div>${action}</header>`}
function settingsSummaryRow(label,value,action=''){return `<div><dt>${label}</dt><dd>${value}</dd>${action}</div>`}
function policySummary(label,enabled){return `<div class="settings-policy-summary">${icon(enabled?'check':'x')}<span>${t(label)}</span><small>${t(enabled?'enabledState':'disabledState')}</small></div>`}

function accountProfileDrawer(){
  openDrawer(t('editProfile'),`<form class="form" id="accountProfileForm">${field(t('displayName'),'displayName','text',state.me.displayName,'required')}<label class="field"><span>${t('username')}</span><input value="${escapeHTML(state.me.username)}" disabled></label><label class="field"><span>${t('interfaceLanguage')}</span><select name="locale"><option value="zh" ${state.locale==='zh'?'selected':''}>简体中文</option><option value="en" ${state.locale==='en'?'selected':''}>English</option></select></label><div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form>`,()=>{$('#accountProfileForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form),data=Object.fromEntries(new FormData(form));button.disabled=true;error.hidden=true;try{const saved=await api('/api/me',{method:'PATCH',body:JSON.stringify({displayName:data.displayName})});state.me={...state.me,...saved,displayName:data.displayName};state.locale=data.locale;localStorage.pbLocale=data.locale;closeDrawer();renderShell()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}});
}

