function attachmentExtension(attachment){const name=String(attachment.original_name||'').toLowerCase(),index=name.lastIndexOf('.');return index>=0?name.slice(index):''}
function readableAttachmentKind(attachment){
  const mime=String(attachment.mime||'').toLowerCase().split(';')[0],extension=attachmentExtension(attachment);
  if(mime==='text/markdown'||['.md','.markdown'].includes(extension))return 'markdown';
  if(mime==='application/json'||['.json','.jsonl','.ndjson'].includes(extension))return 'json';
  if(mime.startsWith('text/')||['.txt','.csv','.tsv','.xml','.yaml','.yml','.log','.ini','.cfg','.conf','.sql','.js','.jsx','.ts','.tsx','.css','.html','.htm','.go','.py','.sh','.ps1','.toml'].includes(extension))return 'text';
  return '';
}
attachmentMarkup=function(attachment){
  const url=`/api/attachments/${encodeURIComponent(attachment.id)}`,image=(attachment.mime||'').startsWith('image/'),previewKind=readableAttachmentKind(attachment);
  if(image)return `<figure class="attachment-image"><a href="${url}" target="_blank" rel="noopener"><img src="${url}" alt="${escapeHTML(attachment.original_name)}" loading="lazy"></a><figcaption>${icon('image')}${escapeHTML(attachment.original_name)} · ${formatFileSize(attachment.size)}</figcaption></figure>`;
  return `<div class="attachment-file"><span>${icon('file')}</span><span><strong>${escapeHTML(attachment.original_name)}</strong><small>${formatFileSize(attachment.size)}</small></span>${previewKind?`<button class="text-action" type="button" data-preview-attachment="${attachment.id}" data-preview-kind="${previewKind}">${t('preview')}</button>`:''}<a class="text-action" href="${url}" download>${t('download')}</a></div>${previewKind?`<div class="text-attachment-preview" id="attachment-preview-${attachment.id}" hidden></div>`:''}`;
};
function wireTextAttachmentPreviews(){document.querySelectorAll('[data-preview-attachment]').forEach(button=>button.onclick=async()=>{const target=$(`#attachment-preview-${CSS.escape(button.dataset.previewAttachment)}`);if(!target.hidden){target.hidden=true;button.textContent=t('preview');return}button.disabled=true;try{const response=await fetch(`/api/attachments/${encodeURIComponent(button.dataset.previewAttachment)}`);if(!response.ok)throw new Error(response.statusText);const source=await response.text();if(button.dataset.previewKind==='markdown')target.innerHTML=safeMarkdown(source);else if(button.dataset.previewKind==='json'){try{target.innerHTML=`<pre>${escapeHTML(JSON.stringify(JSON.parse(source),null,2))}</pre>`}catch{target.innerHTML=`<pre>${escapeHTML(source)}</pre>`}}else target.innerHTML=`<pre>${escapeHTML(source)}</pre>`;target.hidden=false;button.textContent=t('collapsePreview')}catch(error){toast(error.message)}finally{button.disabled=false}})}
