function taskCreatedDateKey(value){
  const date=new Date(value);if(Number.isNaN(date.getTime()))return '';
  const pad=number=>String(number).padStart(2,'0');return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}`;
}

function activeAgentStartedAt(item){
  return [...(item.executions||[])].reverse().find(execution=>execution.state==='running')?.started_at||'';
}

function formatAgentElapsed(startedAt,currentTime=Date.now()){
  const startedTime=new Date(startedAt).getTime();if(Number.isNaN(startedTime))return '00:00';
  const totalSeconds=Math.max(0,Math.floor((currentTime-startedTime)/1000)),hours=Math.floor(totalSeconds/3600),minutes=Math.floor(totalSeconds%3600/60),seconds=totalSeconds%60,pad=value=>String(value).padStart(2,'0');
  return hours?`${pad(hours)}:${pad(minutes)}:${pad(seconds)}`:`${pad(minutes)}:${pad(seconds)}`;
}

function agentRunningMarkup(item,agentName){
  const startedAt=activeAgentStartedAt(item),elapsed=startedAt?`<span class="task-agent-duration" data-agent-started-at="${escapeHTML(startedAt)}" role="timer">${escapeHTML(t('agentElapsed',{duration:formatAgentElapsed(startedAt)}))}</span>`:'';
  return `<span class="agent-running-status">${icon('bot')}<span class="agent-running-copy"><span>${escapeHTML(t('agentRunningLabel',{agent:agentName}))}</span>${elapsed}</span></span>`;
}

function startAgentElapsedClock(){
  clearInterval(state.agentElapsedClock);
  const update=()=>{const timers=document.querySelectorAll('[data-agent-started-at]');timers.forEach(timer=>{timer.textContent=t('agentElapsed',{duration:formatAgentElapsed(timer.dataset.agentStartedAt)})});if(!timers.length){clearInterval(state.agentElapsedClock);state.agentElapsedClock=null}};
  update();if(document.querySelector('[data-agent-started-at]'))state.agentElapsedClock=setInterval(update,1000);
}

