function taskLiveSignature(item){
  const conversation=item.conversation||[],latest=conversation[conversation.length-1];
  return [item.version,item.updated_at,item.stage,item.agent_state,conversation.length,latest?.id||''].join('|');
}
function scheduleTaskLiveRefresh(item){
  clearTimeout(state.taskLiveRefreshTimer);
  const itemID=item.id,baselineSignature=taskLiveSignature(item);
  state.taskLiveRefreshTimer=setTimeout(async()=>{
    if(state.task!==itemID)return;
    const draft=$('#taskMessageInput'),drawer=$('#drawer');
    if(draft?.value||drawer?.classList.contains('open')){scheduleTaskLiveRefresh(item);return}
    try{
      const latest=await api(`/api/work-items/${itemID}`);if(state.task!==itemID)return;
      const latestSignature=taskLiveSignature(latest);
      if(latestSignature!==baselineSignature){await localWorkflowUI.renderTask();return}
      scheduleTaskLiveRefresh(latest);
    }catch{if(state.task===itemID)scheduleTaskLiveRefresh(item)}
  },2000);
}
