async function refreshUnreadMessageBadge(){
  const badgeElement=$('.nav-message-badge');if(!badgeElement)return;
  try{const result=await api('/api/notifications?page=1&pageSize=1'),count=Number(result.unreadCount||0);badgeElement.textContent=count>99?'99+':String(count);badgeElement.hidden=count===0;badgeElement.setAttribute('aria-label',`${t('unread')} ${count}`)}catch{badgeElement.hidden=true}
}

const collapsibleNavigationShell=renderShell;
renderShell=function(){
  if(state.page==='projectSettings'){state.page='settings';state.settingsSection='projects'}
  collapsibleNavigationShell();
  const shell=$('.shell'),rail=$('.rail'),bottom=$('.rail-bottom'),mastActions=$('.mast-actions'),messageButton=$('[data-page="messages"]'),settingsButton=$('[data-page="settings"]'),locale=$('#locale');if(!shell||!rail||!bottom||!mastActions)return;
  if(messageButton){bottom.insertBefore(messageButton,settingsButton||bottom.firstChild);messageButton.title=t('messages');messageButton.setAttribute('aria-label',t('messages'));let unread=$('.nav-message-badge',messageButton);if(!unread){unread=document.createElement('em');unread.className='nav-message-badge';unread.hidden=true;messageButton.append(unread)}}
  if(locale){locale.classList.remove('button','locale-control');locale.classList.add('nav-locale');locale.innerHTML=`${icon('globe')}<span>${state.locale==='zh'?'English':'中文'}</span>`;locale.title=t(state.locale==='zh'?'switchToEnglish':'switchToChinese');bottom.insertBefore(locale,settingsButton||null)}
  state.railCollapsed=localStorage.pbRailCollapsed==='true';shell.classList.toggle('rail-collapsed',state.railCollapsed);
  const collapse=document.createElement('button');collapse.id='railCollapse';collapse.className='rail-toggle';collapse.type='button';collapse.innerHTML=icon('chevron');collapse.title=t(state.railCollapsed?'expandSidebar':'collapseSidebar');collapse.setAttribute('aria-label',collapse.title);collapse.setAttribute('aria-expanded',String(!state.railCollapsed));mastActions.append(collapse);collapse.onclick=()=>{state.railCollapsed=!state.railCollapsed;localStorage.pbRailCollapsed=String(state.railCollapsed);shell.classList.toggle('rail-collapsed',state.railCollapsed);collapse.title=t(state.railCollapsed?'expandSidebar':'collapseSidebar');collapse.setAttribute('aria-label',collapse.title);collapse.setAttribute('aria-expanded',String(!state.railCollapsed))};
  refreshUnreadMessageBadge();
};

renderMessages=async function(){
  state.messageProject=state.messageProject||'';state.messagePage=Math.max(1,state.messagePage||1);const pageSize=10,params=new URLSearchParams({page:String(state.messagePage),pageSize:String(pageSize)});if(state.messageProject)params.set('projectId',state.messageProject);
  const result=await api(`/api/notifications?${params}`),notifications=result.items||[],total=Number(result.total||0),pages=Math.max(1,Math.ceil(total/pageSize)),filteredUnread=Number(result.filteredUnreadCount||0);
  if(state.messagePage>pages){state.messagePage=pages;return renderMessages()}
  const projectOptions=`<option value="">${t('allMessageProjects')}</option>${state.projects.map(project=>`<option value="${project.id}" ${state.messageProject===project.id?'selected':''}>${escapeHTML(project.name)}</option>`).join('')}`;
  const actions=filteredUnread?`<button class="button" id="markAllRead">${icon('check')}${t('markAllRead')}</button>`:'';
  const rows=notifications.map(item=>`<button class="message-center-row ${item.read_at?'':'unread'}" data-notification="${item.id}" data-work-item="${item.work_item_id||''}" data-project="${item.project_id||''}"><span class="message-center-icon">${icon(item.kind==='comment'||item.kind==='mention'?'message':item.kind==='assigned'?'users':'activity')}</span><span class="message-center-copy"><span class="message-center-meta"><span class="message-project-tag">${escapeHTML(item.project_name||t('systemMessageProject'))}</span><time>${taskDate(item.created_at)}</time></span><strong>${escapeHTML(item.work_item_title||item.title||item.work_item_id||'ProjectBoard')}</strong><p>${escapeHTML(item.body||item.title||'')}</p></span>${item.read_at?'':`<i class="message-unread-dot" aria-label="${t('unread')}"></i>`}<span class="message-center-arrow">${icon('chevron')}</span></button>`).join('');
  $('#workspace').innerHTML=header(t('myMessages'),t('notificationCenter'),actions)+`<div class="content message-center-page"><section class="message-center-toolbar"><label><span>${t('projectFilter')}</span><select id="messageProjectFilter">${projectOptions}</select></label><div><strong>${t('messageCount',{count:total})}</strong><span>${filteredUnread} ${t('unread')}</span></div></section><section class="message-center-list">${rows||`<div class="message-center-empty">${icon('message')}<strong>${t('noNotifications')}</strong><p>${t('noNotificationsNote')}</p></div>`}</section><nav class="message-pagination" aria-label="${escapeHTML(t('myMessages'))}"><button class="button" id="previousMessages" ${state.messagePage<=1?'disabled':''}>${icon('chevron')}${t('previousPage')}</button><span>${t('pageOf',{page:state.messagePage,pages})}</span><button class="button" id="nextMessages" ${state.messagePage>=pages?'disabled':''}>${t('nextPage')}${icon('chevron')}</button></nav></div>`;
  $('#messageProjectFilter').onchange=event=>{state.messageProject=event.target.value;state.messagePage=1;renderMessages()};
  $('#previousMessages').onclick=()=>{if(state.messagePage>1){state.messagePage--;renderMessages()}};$('#nextMessages').onclick=()=>{if(state.messagePage<pages){state.messagePage++;renderMessages()}};
  const readAll=$('#markAllRead');if(readAll)readAll.onclick=async()=>{const suffix=state.messageProject?`?projectId=${encodeURIComponent(state.messageProject)}`:'';await api(`/api/notifications/read-all${suffix}`,{method:'POST',body:'{}'});await renderMessages()};
  document.querySelectorAll('[data-notification]').forEach(row=>row.onclick=async()=>{await api(`/api/notifications/${row.dataset.notification}/read`,{method:'POST',body:'{}'});if(row.dataset.workItem){const project=state.projects.find(item=>item.id===row.dataset.project);if(project){state.project=project;localStorage.pbProject=project.id}state.page='queue';state.task=row.dataset.workItem;renderShell()}else await renderMessages()});
  refreshUnreadMessageBadge();writeCurrentRoute();
};

