function splitAgentTags(value=''){return [...new Set(String(value).split(',').map(tag=>tag.trim()).filter(Boolean))]}

projectForm=function(){openDrawer(t('createProject'),formShell(
  field(t('name'),'name','text','','required')+
  field(t('projectKey'),'key','text','','required pattern="[A-Za-z][A-Za-z0-9-]{1,19}"')+
  field(t('projectPathLabel'),'projectPath','text','','required')+
  `<p class="drawer-note">${t('projectPathNote')}</p>`
),()=>wireForm('#drawerForm',data=>api('/api/projects',{method:'POST',body:JSON.stringify(data)})))};

editProjectForm=function(project){openDrawer(t('editProject'),formShell(
  field(t('name'),'name','text',project.name,'required')+
  `<label class="field"><span>${t('projectPathLabel')}</span><input value="${escapeHTML(project.projectPath)}" disabled><small>${t('workflowImmutable')}</small></label>`+
  field(t('defaultTargetBranch'),'defaultTargetBranch','text',project.defaultTargetBranch,'required')
),()=>wireForm('#drawerForm',data=>api(`/api/projects/${project.id}`,{method:'PATCH',body:JSON.stringify(data)})))};

managedProjectIdentity=function(project,tab){managedProjectForm(t('editProject'),
  field(t('name'),'name','text',project.name,'required')+
  `<label class="field"><span>${t('projectPathLabel')}</span><input value="${escapeHTML(project.projectPath)}" disabled></label>`+
  field(t('defaultTargetBranch'),'defaultTargetBranch','text',project.defaultTargetBranch,'required'),
  project,tab,data=>api(`/api/projects/${project.id}`,{method:'PATCH',body:JSON.stringify(data)}))
};

const localProjectPanel=managedProjectPanel;
