phaseMarkup=function(item){const flow=item.workflow_type==='simple_conversation'?['created','in_progress','closed']:['created','in_progress','completed','closed'],current=flow.indexOf(item.stage);return flow.map((stage,index)=>`<div class="phase-band-step ${index<current?'done':index===current?'active':''}" role="listitem" ${index===current?'aria-current="step"':''}><span class="phase-node-mark">${index<current?icon('check'):index+1}</span><span class="phase-node-copy"><strong>${t(stage)}</strong></span></div>`).join('')};

stageForm=function(item){
  const transitions=item.workflow_type==='simple_conversation'?({created:['in_progress'],in_progress:['closed']}[item.stage]||[]):({created:['in_progress'],in_progress:['completed'],completed:['in_progress','closed']}[item.stage]||[]);
  if(item.blocked_at){openDrawer(t('stageAction'),formShell(`<p class="drawer-note">${t('clearBlockedNote')}</p>`),()=>wireForm('#drawerForm',()=>api(`/api/work-items/${item.id}/unblock`,{method:'POST',body:JSON.stringify({expectedVersion:item.version})})));return}
  openDrawer(t('stageAction'),`<form class="form" id="drawerForm"><label class="field"><span>${t('targetStage')}</span><select name="targetStage">${transitions.map(stage=>`<option value="${stage}">${t(stage)}</option>`).join('')}</select></label>${area(t('changeStageNote'),'noteMarkdown')}<div class="form-error" hidden></div><button class="button primary" type="submit" ${transitions.length?'':'disabled'}>${t('save')}</button></form>`,()=>wireForm('#drawerForm',data=>api(`/api/work-items/${item.id}/stage`,{method:'POST',body:JSON.stringify({...data,expectedVersion:item.version})})))
};

const repositoryTaskRenderer=renderTask;
renderTask=async function(){
  await repositoryTaskRenderer();const item=await api(`/api/work-items/${state.task}`),panel=$('.task-basic-list');
  if(panel&&item.is_agent_task&&item.agent_state==='queued'&&!item.assigned_agent_id)panel.insertAdjacentHTML('beforeend',`<div><dt>Agent</dt><dd>${t('noAvailableAgent')}</dd></div>`);
  const oldResume=$('#continueAgent');if(oldResume)oldResume.remove();
  if(!String(item.agent_state||'').startsWith('paused_'))return;
  $('#advanceTaskStage')?.remove();
  const actions=$('.chat-header-actions');if(!actions)return;const review=document.createElement('span');review.className='agent-review-actions';
  const primary=item.agent_phase==='merge_review'?['confirm_merge','mergeChanges']:item.agent_phase==='close_review'?['confirm_close','closeTask']:['continue_work','continueAgent'];
  review.innerHTML=`${['merge_review','close_review'].includes(item.agent_phase)?`<button class="button" data-agent-action="continue_work">${t('continueWork')}</button>`:''}<button class="button primary" data-agent-action="${primary[0]}">${t(primary[1])}</button>`;actions.append(review);
  review.querySelectorAll('[data-agent-action]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api(`/api/work-items/${item.id}/agent-action`,{method:'POST',body:JSON.stringify({expectedVersion:item.version,action:button.dataset.agentAction,markdown:''})});await renderTask()}catch(error){toast(error.message);button.disabled=false}})
};

