function agentLiveOutput(agent){
  const session=crypto.randomUUID();state.agentLiveSession=session;
  openDrawer(t('liveAgentOutput'),`<div class="agent-live-shell"><header class="agent-live-intro"><button class="text-action" id="backToAgent" type="button">${icon('chevron')}${t('backToAgent')}</button><p>${t('liveOutputNote')}</p></header><div class="agent-live-tabs" id="agentLiveTabs" role="tablist"></div><section class="agent-live-stage" aria-live="polite"><header id="agentLiveMeta"><span class="agent-live-pulse"></span><strong>${escapeHTML(agent.name)}</strong></header><div class="agent-live-notice" id="agentLiveNotice" hidden></div><pre id="agentLiveOutput" tabindex="0">${escapeHTML(t('waitingForOutput'))}</pre></section></div>`,drawer=>{
    drawer.classList.add('agent-live-drawer');
    $('#backToAgent').onclick=()=>{state.agentLiveSession='';localAgentDrawer(agent)};
  });
  let selected='';
  const refresh=async()=>{
    if(state.agentLiveSession!==session||!$('#drawer')?.classList.contains('open'))return;
    try{
      const executions=await api(`/api/agents/${encodeURIComponent(agent.id)}/executions/current`),tabs=$('#agentLiveTabs'),output=$('#agentLiveOutput'),meta=$('#agentLiveMeta'),notice=$('#agentLiveNotice');
      if(!tabs||!output||!meta||!notice)return;
      if(!executions.some(execution=>execution.id===selected))selected=executions[0]?.id||'';
      tabs.innerHTML=executions.map(execution=>`<button type="button" role="tab" aria-selected="${execution.id===selected}" data-live-execution="${escapeHTML(execution.id)}"><strong>${escapeHTML(execution.workItemId)}</strong><span>${escapeHTML(execution.title)}</span></button>`).join('');
      tabs.hidden=executions.length<2;
      tabs.querySelectorAll('[data-live-execution]').forEach(button=>button.onclick=()=>{selected=button.dataset.liveExecution;refresh()});
      const execution=executions.find(item=>item.id===selected);
      if(!execution){meta.innerHTML=`<span class="agent-live-pulse idle"></span><strong>${escapeHTML(agent.name)}</strong>`;notice.hidden=true;output.textContent=t('noRunningExecutions');return}
      const follow=output.scrollHeight-output.scrollTop-output.clientHeight<40;
      meta.innerHTML=`<span class="agent-live-pulse"></span><strong>${escapeHTML(execution.workItemId)} · ${escapeHTML(execution.title)}</strong><time role="timer">${escapeHTML(formatAgentElapsed(execution.startedAt))}</time>`;
      notice.textContent=execution.truncated?t('outputTruncated'):'';notice.hidden=!execution.truncated;
      output.textContent=execution.output||t('waitingForOutput');if(follow)output.scrollTop=output.scrollHeight;
    }catch(error){const notice=$('#agentLiveNotice');if(notice){notice.textContent=t('liveOutputError');notice.hidden=false}}
    if(state.agentLiveSession===session)setTimeout(refresh,1000);
  };
  refresh();
}

localAgentDrawer=function(agent){
  const liveButton=(agent.currentLoad||0)>0?`<button class="button primary" id="viewAgentLiveOutput" type="button">${icon('terminal')}${t('viewLiveOutput')}</button>`:'';
  openDrawer(t('agentManagement'),`<section class="entity-summary"><span class="entity-mark">${icon('bot')}</span><div><span class="eyebrow">${t('localCodexCLI')}</span><h3>${escapeHTML(agent.name)}</h3><p>${escapeHTML(agent.purpose||t('noPurpose'))}</p></div></section><section class="drawer-section"><dl class="settings-summary-rows">${settingsSummaryRow(t('agentRuntime'),t('localCodexCLI'))}${settingsSummaryRow(t('maxConcurrentTasks'),String(agent.maxConcurrentTasks||1))}${settingsSummaryRow(t('turnTimeoutMinutes'),String(agent.turnTimeoutMinutes||120))}${settingsSummaryRow(t('currentLoad'),`${agent.currentLoad||0} / ${agent.maxConcurrentTasks||1}`)}</dl></section>${liveButton?`<section class="drawer-section agent-live-action"><p>${t('liveOutputNote')}</p>${liveButton}</section>`:''}<section class="drawer-section"><p>${t('agentManagementNote')}</p></section><section class="drawer-section"><button class="button danger" id="deleteManagedAgent" type="button">${icon('trash')}${t('deleteAgent')}</button></section>`,()=>{$('#viewAgentLiveOutput')?.addEventListener('click',()=>agentLiveOutput(agent));$('#deleteManagedAgent').onclick=()=>logicalDeleteDrawer('agent',agent)});
};
