Object.assign(messages.en,{knowledge:'Knowledge',knowledgeNote:'Project knowledge organized as a hierarchy and maintained by members and Agents.',knowledgeTree:'Project knowledge tree',knowledgeNodeCount:'{count} nodes',knowledgeUpdated:'Updated {time} · {actor}',knowledgeNoResults:'No matching knowledge nodes',synced:'Synced',agentLockedShort:'Agent locked',agentEditable:'Agent editable',agentRequests:'Agent requests',agentRequestsNote:'Every Agent run is a one-shot request with a durable result.',newKnowledgeNode:'New node',newChildNode:'New child',nodeTitle:'Node title',nodeSummary:'Knowledge summary',nodeSummaryNote:'Describe this knowledge in one or two sentences. Agents see this before the full content.',nodeTrigger:'When to use',nodeTriggerNote:'Describe the tasks, paths, phases, or uncertainties that should trigger retrieval.',nodeMarkdown:'Markdown content',noKnowledge:'The knowledge base is empty',noKnowledgeNote:'Create the first node to establish durable project context.',lockedForAgents:'Locked for Agent edits',lockForAgents:'Lock Agent edits',unlockForAgents:'Unlock Agent edits',revisionHistory:'Revision history',restoreRevision:'Restore revision',agentRequest:'Ask Agent',planFirst:'Plan first',executeNow:'Execute now',retryRequest:'Create retry request',cancelRequest:'Cancel request',approvePlan:'Approve plan and execute',requestType:'Request type',sourceTask:'Source task',rawLog:'Raw log',noAgentRequests:'No Agent requests',noAgentRequestsNote:'Task actions and knowledge maintenance create requests here automatically.',projectRoot:'Project root',knowledgeSaved:'Knowledge node saved',requestCreated:'Agent request created',delete:'Delete'});

const knowledgeBaseRoute=currentRouteHash;
currentRouteHash=function(){const base=projectRouteBase();if(base&&state.page==='knowledge')return `#${base}/knowledge`;if(base&&state.page==='agentRequests')return `#${base}/agent-requests`;return knowledgeBaseRoute()};
const knowledgeApplyRoute=applyRouteFromURL;
applyRouteFromURL=function(){knowledgeApplyRoute();const parts=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean).map(part=>{try{return decodeURIComponent(part)}catch{return part}});if(parts[0]==='projects'&&parts[2]==='knowledge'){state.page='knowledge';state.task=null}if(parts[0]==='projects'&&parts[2]==='agent-requests'){state.page='agentRequests';state.task=null}};

const knowledgePageRouter=renderPage;
renderPage=async function(){if(state.page==='knowledge')return renderKnowledge();if(state.page==='agentRequests')return renderAgentRequests();return knowledgePageRouter()};

const knowledgeShell=renderShell;
renderShell=function(){knowledgeShell();const primary=$('.rail .nav');if(!primary||!state.project)return;const queue=primary.querySelector('[data-page="queue"]');for(const [page,label,iconName] of [['agentRequests','agentRequests','bot'],['knowledge','knowledge','book-open']]){let button=primary.querySelector(`[data-page="${page}"]`);if(!button){button=document.createElement('button');button.dataset.page=page;button.innerHTML=`${icon(iconName)}<span>${t(label)}</span>`;queue?.after(button);button.onclick=()=>navigate(page)}button.classList.toggle('active',state.page===page)}};

const knowledgeCollapsedNodes=new Set();
function knowledgeSearchText(node){return `${node.title}\n${node.summary||''}\n${node.triggerDescription||''}\n${node.markdown||''}`}
function knowledgeFilteredIDs(nodes,query){const term=query.trim().toLocaleLowerCase();if(!term)return new Set(nodes.map(node=>node.id));const byID=new Map(nodes.map(node=>[node.id,node])),visible=new Set();for(const node of nodes){if(!knowledgeSearchText(node).toLocaleLowerCase().includes(term))continue;visible.add(node.id);let current=node;while(current?.parentId&&byID.has(current.parentId)){visible.add(current.parentId);current=byID.get(current.parentId)}}return visible}
function knowledgePath(nodes,node){const byID=new Map(nodes.map(item=>[item.id,item])),path=[],seen=new Set();let current=node;while(current&&!seen.has(current.id)){seen.add(current.id);path.unshift(current);current=current.parentId?byID.get(current.parentId):null}return path}
function knowledgeTreeMarkup(nodes,parentID=null,visibleIDs=new Set(nodes.map(node=>node.id)),query=''){const children=nodes.filter(node=>(node.parentId||null)===parentID&&visibleIDs.has(node.id));if(!children.length)return '';return `<ul class="knowledge-tree-level">${children.map(node=>{const childCount=nodes.filter(candidate=>candidate.parentId===node.id).length,hasVisibleChildren=nodes.some(candidate=>candidate.parentId===node.id&&visibleIDs.has(candidate.id)),collapsed=!query&&knowledgeCollapsedNodes.has(node.id);return `<li class="knowledge-tree-item ${collapsed?'collapsed':''}"><button class="knowledge-tree-node ${state.knowledgeNode===node.id?'active':''}" data-knowledge-node="${node.id}"><span class="knowledge-tree-toggle ${hasVisibleChildren?'':'placeholder'}" ${hasVisibleChildren?`data-knowledge-toggle="${node.id}"`:''}>${icon('chevron')}</span><span class="knowledge-tree-icon">${icon(node.lockedForAgents?'lock':hasVisibleChildren?'book-open':'file')}</span><span class="knowledge-tree-copy"><strong>${escapeHTML(node.title)}</strong><small>V${node.version}${node.lockedForAgents?` · ${t('lockedForAgents')}`:''}</small></span>${childCount?`<span class="knowledge-tree-count">${childCount}</span>`:''}</button>${collapsed?'':knowledgeTreeMarkup(nodes,node.id,visibleIDs,query)}</li>`}).join('')}</ul>`}
function knowledgeBreadcrumbMarkup(nodes,node){return knowledgePath(nodes,node).map((item,index,path)=>`${index?icon('chevron'):''}<span class="${index===path.length-1?'current':''}">${escapeHTML(item.title)}</span>`).join('')}
async function renderKnowledge(){if(!state.project)return renderQueue();const query=state.knowledgeQuery||'',nodes=await api(`/api/projects/${state.project.id}/knowledge`),visibleIDs=knowledgeFilteredIDs(nodes,query),matchingCount=query?nodes.filter(node=>knowledgeSearchText(node).toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())).length:nodes.length;state.knowledgeNodes=nodes;if(state.knowledgeNode&&!visibleIDs.has(state.knowledgeNode))state.knowledgeNode=null;const selected=nodes.find(node=>node.id===state.knowledgeNode)||(query?nodes.find(node=>visibleIDs.has(node.id)&&knowledgeSearchText(node).toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())):nodes[0])||null;if(selected)state.knowledgeNode=selected.id;const actions=`<button class="button primary" id="newKnowledge">${icon('plus')}${t('newKnowledgeNode')}</button>`,tree=knowledgeTreeMarkup(nodes,null,visibleIDs,query);$('#workspace').innerHTML=header(t('knowledge'),t('knowledgeNote'),actions)+`<div class="content knowledge-workspace"><aside class="knowledge-index"><label class="search">${icon('search')}<input id="knowledgeSearch" value="${escapeHTML(query)}" placeholder="${t('search')}"></label><div class="knowledge-tree-meta"><strong>${t('knowledgeTree')}</strong><span>${t('knowledgeNodeCount',{count:matchingCount})}</span></div><div class="knowledge-tree">${tree||`<div class="knowledge-empty">${icon('book-open')}<strong>${t(query?'knowledgeNoResults':'noKnowledge')}</strong><p>${query?'':t('noKnowledgeNote')}</p></div>`}</div></aside><section class="knowledge-document">${selected?knowledgeDocumentMarkup(selected,nodes):`<div class="knowledge-blank">${icon('book-open')}<h2>${t('noKnowledge')}</h2><p>${t('noKnowledgeNote')}</p></div>`}</section></div>`;$('#newKnowledge').onclick=()=>knowledgeEditor(null,null);document.querySelectorAll('[data-knowledge-node]').forEach(button=>button.onclick=event=>{const toggle=event.target.closest('[data-knowledge-toggle]');if(toggle){event.stopPropagation();const id=toggle.dataset.knowledgeToggle;knowledgeCollapsedNodes.has(id)?knowledgeCollapsedNodes.delete(id):knowledgeCollapsedNodes.add(id);return renderKnowledge()}state.knowledgeNode=button.dataset.knowledgeNode;renderKnowledge()});let searchTimer;$('#knowledgeSearch').oninput=event=>{clearTimeout(searchTimer);const value=event.target.value;searchTimer=setTimeout(async()=>{state.knowledgeQuery=value;state.knowledgeNode=null;await renderKnowledge();const input=$('#knowledgeSearch');input?.focus();input?.setSelectionRange(value.length,value.length)},180)};if(selected)wireKnowledgeDocument(selected)}
function knowledgeDocumentMarkup(node,nodes){const actor=t(node.updatedByType==='agent'?'agent':'human'),status=t(node.lockedForAgents?'agentLockedShort':'agentEditable');return `<div class="knowledge-breadcrumb"><span>${t('knowledge')}</span>${icon('chevron')}${knowledgeBreadcrumbMarkup(nodes,node)}</div><header class="knowledge-document-head"><div><span class="knowledge-status"><i></i>${t('synced')} · V${node.version} · ${status}</span><h2>${escapeHTML(node.title)}</h2><p>${t('knowledgeUpdated',{time:taskDate(node.updatedAt),actor})}</p></div><div class="knowledge-document-actions"><button class="button" id="knowledgeHistory">${icon('history')}${t('revisionHistory')}</button><button class="button knowledge-icon-action" id="knowledgeLock" title="${t(node.lockedForAgents?'unlockForAgents':'lockForAgents')}">${icon('lock')}<span>${t(node.lockedForAgents?'unlockForAgents':'lockForAgents')}</span></button><button class="button" id="knowledgeEdit">${icon('edit')}${t('edit')}</button><button class="button" id="knowledgeChild">${icon('plus')}${t('newChildNode')}</button></div></header><aside class="knowledge-discovery"><div><strong>${t('nodeSummary')}</strong><p>${escapeHTML(node.summary||'—')}</p></div><div><strong>${t('nodeTrigger')}</strong><p>${escapeHTML(node.triggerDescription||'—')}</p></div></aside><article class="knowledge-markdown"><pre>${escapeHTML(node.markdown||'')}</pre></article><footer class="knowledge-path">${icon('book-open')}<span>${knowledgePath(nodes,node).map(item=>escapeHTML(item.title)).join(' / ')}</span></footer>`}
function wireKnowledgeDocument(node){$('#knowledgeEdit').onclick=()=>knowledgeEditor(node,node.parentId);$('#knowledgeChild').onclick=()=>knowledgeEditor(null,node.id);$('#knowledgeLock').onclick=async()=>{try{await api(`/api/knowledge/nodes/${node.id}/lock`,{method:'POST',body:JSON.stringify({expectedVersion:node.version,locked:!node.lockedForAgents})});await renderKnowledge()}catch(error){toast(error.message)}};$('#knowledgeHistory').onclick=()=>knowledgeHistory(node)}
function knowledgeEditor(node,parentID){const parents=(state.knowledgeNodes||[]).filter(candidate=>!node||candidate.id!==node.id).map(candidate=>`<option value="${candidate.id}" ${(parentID||'')===candidate.id?'selected':''}>${escapeHTML(candidate.title)}</option>`).join('');openDrawer(t(node?'edit':'newKnowledgeNode'),`<form class="form" id="knowledgeForm"><label class="field"><span>${t('projectRoot')}</span><select name="parentId"><option value="">${t('projectRoot')}</option>${parents}</select></label><label class="field"><span>${t('nodeTitle')}</span><input name="title" value="${escapeHTML(node?.title||'')}" required maxlength="200"></label><label class="field"><span>${t('nodeSummary')}</span><textarea name="summary" rows="3" maxlength="1000">${escapeHTML(node?.summary||'')}</textarea><small>${t('nodeSummaryNote')}</small></label><label class="field"><span>${t('nodeTrigger')}</span><textarea name="triggerDescription" rows="3" maxlength="1000">${escapeHTML(node?.triggerDescription||'')}</textarea><small>${t('nodeTriggerNote')}</small></label><label class="field"><span>${t('nodeMarkdown')}</span><textarea name="markdown" rows="16">${escapeHTML(node?.markdown||'')}</textarea></label><div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button>${node?`<button class="button danger" id="deleteKnowledge" type="button">${icon('trash')}${t('delete')}</button>`:''}</form>`,()=>{$('#knowledgeForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,error=$('.form-error',form),button=$('button[type=submit]',form),data=Object.fromEntries(new FormData(form));button.disabled=true;error.hidden=true;try{const payload={parentId:data.parentId,title:data.title,summary:data.summary,triggerDescription:data.triggerDescription,markdown:data.markdown};const saved=node?await api(`/api/knowledge/nodes/${node.id}`,{method:'PATCH',body:JSON.stringify({...payload,expectedVersion:node.version})}):await api(`/api/projects/${state.project.id}/knowledge`,{method:'POST',body:JSON.stringify(payload)});state.knowledgeNode=saved.id;closeDrawer();toast(t('knowledgeSaved'));await renderKnowledge()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}};$('#deleteKnowledge')?.addEventListener('click',async()=>{try{await api(`/api/knowledge/nodes/${node.id}?expectedVersion=${node.version}`,{method:'DELETE'});state.knowledgeNode=null;closeDrawer();await renderKnowledge()}catch(error){toast(error.message)}})})}
async function knowledgeHistory(node){const revisions=await api(`/api/knowledge/nodes/${node.id}/revisions`);openDrawer(t('revisionHistory'),`<div class="revision-list">${revisions.map(revision=>`<section><div><strong>V${revision.version}</strong><small>${taskDate(revision.createdAt)} · ${escapeHTML(revision.actorType)}</small></div><p>${escapeHTML(revision.reason||'')}</p>${revision.version!==node.version?`<button class="button" data-restore-version="${revision.version}">${t('restoreRevision')}</button>`:''}</section>`).join('')}</div>`,drawer=>drawer.querySelectorAll('[data-restore-version]').forEach(button=>button.onclick=async()=>{try{await api(`/api/knowledge/nodes/${node.id}/restore`,{method:'POST',body:JSON.stringify({expectedVersion:node.version,revisionVersion:Number(button.dataset.restoreVersion)})});closeDrawer();await renderKnowledge()}catch(error){toast(error.message)}}))}

