async function renderAgentRequests(){if(!state.project)return renderQueue();const requests=await api(`/api/agent-requests?projectId=${encodeURIComponent(state.project.id)}`),rows=requests.map(request=>`<button class="agent-request-row" data-agent-request="${request.id}"><span class="request-status ${request.status}">${icon(request.status==='running'?'activity':request.status==='succeeded'?'check':'bot')}</span><span><strong>${escapeHTML(request.title)}</strong><small>${escapeHTML(request.id)} · ${escapeHTML(requestKindLabel[request.kind]||request.kind)}</small></span>${badge(request.status,request.status==='succeeded'?'signal':request.status==='failed'?'danger':'')}</button>`).join('');$('#workspace').innerHTML=header(t('agentRequests'),t('agentRequestsNote'))+`<div class="content agent-requests-page">${rows||`<div class="knowledge-blank">${icon('bot')}<h2>${t('noAgentRequests')}</h2><p>${t('noAgentRequestsNote')}</p></div>`}</div>`;document.querySelectorAll('[data-agent-request]').forEach(button=>button.onclick=()=>agentRequestDetail(button.dataset.agentRequest))}
async function agentRequestDetail(id){const request=await api(`/api/agent-requests/${id}`),terminal=['succeeded','failed','cancelled'].includes(request.status),result=request.finalMessage||request.resultJson||'',actions=`${request.kind==='task_plan'&&request.status==='succeeded'?`<button class="button primary" id="approvePlan">${icon('check')}${t('approvePlan')}</button>`:''}${terminal?`<button class="button" id="retryRequest">${icon('history')}${t('retryRequest')}</button>`:`<button class="button danger" id="cancelRequest">${icon('x')}${t('cancelRequest')}</button>`}`;openDrawer(request.id,`<section class="agent-request-detail"><header><span>${badge(request.status,request.status==='succeeded'?'signal':request.status==='failed'?'danger':'')}</span><h3>${escapeHTML(request.title)}</h3><p>${escapeHTML(requestKindLabel[request.kind]||request.kind)}${request.sourceWorkItemId?` · ${escapeHTML(request.sourceWorkItemId)}`:''}</p></header><article><h4>${t('outcome')}</h4><pre>${escapeHTML(result||'—')}</pre></article>${request.outputJsonl?`<details><summary>${t('rawLog')}</summary><pre>${escapeHTML(request.outputJsonl)}</pre></details>`:''}<div class="drawer-actions">${actions}</div></section>`,()=>{$('#approvePlan')?.addEventListener('click',async()=>{await api(`/api/agent-requests/${id}/approve-plan`,{method:'POST',body:'{}'});closeDrawer();toast(t('requestCreated'));renderAgentRequests()});$('#retryRequest')?.addEventListener('click',async()=>{await api(`/api/agent-requests/${id}/retry`,{method:'POST',body:'{}'});closeDrawer();toast(t('requestCreated'));renderAgentRequests()});$('#cancelRequest')?.addEventListener('click',async()=>{await api(`/api/agent-requests/${id}/cancel`,{method:'POST',body:'{}'});closeDrawer();renderAgentRequests()})})}

