renderAgentManagement=async function(){
  const agents=await api('/api/agents'),enabledAgents=agents.filter(agent=>agent.status==='active'),running=enabledAgents.reduce((sum,agent)=>sum+(agent.currentLoad||0),0),capacity=enabledAgents.reduce((sum,agent)=>sum+(agent.maxConcurrentTasks||1),0),available=Math.max(0,capacity-running),totalTokens=agents.reduce((sum,agent)=>sum+Number(agent.totalTokens||0),0),actions=`<button class="button primary" id="createManagedAgent">${icon('plus')}${t('createAgent')}</button>`,agentManagementPageSize=10;
  state.agentStatusFilter=['all','active','disabled'].includes(state.agentStatusFilter)?state.agentStatusFilter:'all';
  const filteredAgents=state.agentStatusFilter==='all'?agents:agents.filter(agent=>agent.status===state.agentStatusFilter),pages=Math.max(1,Math.ceil(filteredAgents.length/agentManagementPageSize));
  state.agentManagementPage=Math.min(pages,Math.max(1,state.agentManagementPage||1));
  const pageAgents=filteredAgents.slice((state.agentManagementPage-1)*agentManagementPageSize,state.agentManagementPage*agentManagementPageSize),rows=pageAgents.map(agent=>{const enabled=agent.status==='active',load=agent.currentLoad||0,maximum=agent.maxConcurrentTasks||1,usage=Math.min(100,Math.round(load/maximum*100)),stateKey=enabled?(load>=maximum?'capacityFull':load>0?'capacityBusy':'capacityReady'):'disabled',stateClass=enabled?(load>=maximum?'full':load>0?'busy':'ready'):'disabled',runtime=[agent.model||t('inheritCodexConfig'),reasoningLabel(agent.reasoningEffort)].join(' · ');return `<div class="agent-ops-row ${enabled?'':'is-disabled'}"><button class="agent-ops-row-hit" type="button" data-managed-agent="${agent.id}" aria-label="${escapeHTML(agent.name)}"></button><span class="agent-ops-avatar">${icon('bot')}<i class="${stateClass}"></i></span><span class="agent-ops-identity"><strong>${escapeHTML(agent.name)}</strong><small>${escapeHTML(agent.purpose||t('noPurpose'))}</small><span>${escapeHTML(runtime)}</span></span><span class="agent-ops-capacity"><span><small>${t(stateKey)}</small><strong>${load} / ${maximum}</strong></span><span class="agent-capacity-track"><i style="width:${usage}%"></i></span></span><span class="agent-ops-timeout"><small>${t('totalTokens')}</small><strong>${tokenNumber(agent.totalTokens)}</strong></span><button class="agent-status-switch" type="button" role="switch" aria-checked="${enabled}" aria-label="${t(enabled?'disableAgentAction':'enableAgentAction')} ${escapeHTML(agent.name)}" title="${t(enabled?'disabled':'enabled')}" data-agent-toggle="${agent.id}" data-agent-enabled="${enabled}"><span></span></button><span class="agent-ops-arrow">${icon('chevron')}</span></div>`}).join('');
  const filter=`<div class="agent-ops-toolbar"><label for="agentStatusFilter"><span>${icon('filter')}${t('agentStatusFilter')}</span><select id="agentStatusFilter"><option value="all" ${state.agentStatusFilter==='all'?'selected':''}>${t('allAgentStatuses')}</option><option value="active" ${state.agentStatusFilter==='active'?'selected':''}>${t('enabledAgentStatus')}</option><option value="disabled" ${state.agentStatusFilter==='disabled'?'selected':''}>${t('disabledAgentStatus')}</option></select></label><strong>${t('agentFilterCount',{filtered:filteredAgents.length,total:agents.length})}</strong></div>`,empty=agents.length?`<div class="agent-ops-empty agent-ops-filter-empty">${icon('filter')}<strong>${t('noAgentsForStatus')}</strong><p>${t('noAgentsForStatusNote')}</p></div>`:`<div class="agent-ops-empty">${icon('bot')}<strong>${t('agentManagement')}</strong><p>${t('agentManagementNote')}</p></div>`,pagination=filteredAgents.length?`<nav class="agent-ops-pagination" aria-label="${escapeHTML(t('settingsAgents'))}"><button class="button" id="previousAgents" ${state.agentManagementPage<=1?'disabled':''}>${icon('chevron')}${t('previousPage')}</button><span>${t('pageOf',{page:state.agentManagementPage,pages})}</span><button class="button" id="nextAgents" ${state.agentManagementPage>=pages?'disabled':''}>${t('nextPage')}${icon('chevron')}</button></nav>`:'';
  $('#workspace').innerHTML=header(t('settingsAgents'),t('settingsAgentCopy'),actions)+`<div class="content agent-ops-content organization-agent-ops"><section class="agent-ops-summary" aria-label="${escapeHTML(t('organizationCapacity'))}"><div class="agent-ops-summary-title"><span>${icon('activity')}</span><div><strong>${t('organizationCapacity')}</strong><small>${t('totalTokens')} · ${tokenNumber(totalTokens)}</small></div></div><dl><div><dt>${t('enabledAgents')}</dt><dd>${enabledAgents.length}</dd></div><div><dt>${t('runningTasks')}</dt><dd>${running}</dd></div><div><dt>${t('availableCapacity')}</dt><dd>${available}</dd></div></dl></section><section class="agent-ops-roster"><header><div><h2>${t('organizationIdentity')}</h2><p>${t('settingsAgentCopy')}</p></div><span>${agents.length}</span></header>${filter}${rows?`<div class="agent-ops-list">${rows}</div>`:empty}${pagination}</section></div>`;
  $('#createManagedAgent').onclick=agentForm;$('#agentStatusFilter').onchange=event=>{state.agentStatusFilter=event.currentTarget.value;state.agentManagementPage=1;renderSettingsHub()};$('#previousAgents')?.addEventListener('click',()=>{if(state.agentManagementPage>1){state.agentManagementPage--;renderSettingsHub()}});$('#nextAgents')?.addEventListener('click',()=>{if(state.agentManagementPage<pages){state.agentManagementPage++;renderSettingsHub()}});document.querySelectorAll('[data-managed-agent]').forEach(row=>row.onclick=()=>localAgentDrawer(agents.find(agent=>agent.id===row.dataset.managedAgent)));document.querySelectorAll('[data-agent-toggle]').forEach(toggle=>toggle.onclick=async()=>{const enabled=toggle.dataset.agentEnabled==='true';toggle.disabled=true;try{await api(`/api/agents/${toggle.dataset.agentToggle}/${enabled?'disable':'enable'}`,{method:'POST',body:'{}'});await renderSettingsHub()}catch(error){toast(error.message);toggle.disabled=false}})
};

agentRequestDetail=async function(id){const request=await api(`/api/agent-requests/${id}`),terminal=['succeeded','failed','cancelled'].includes(request.status),result=request.finalMessage||request.resultJson||'',actions=`${request.kind==='task_plan'&&request.status==='succeeded'?`<button class="button primary" id="approvePlan">${icon('check')}${t('approvePlan')}</button>`:''}${terminal?`<button class="button" id="retryRequest">${icon('history')}${t('retryRequest')}</button>`:`<button class="button danger" id="cancelRequest">${icon('x')}${t('cancelRequest')}</button>`}`,runtime=request.model||request.reasoningEffort?`<dl class="settings-summary-rows">${settingsSummaryRow(t('codexModel'),escapeHTML(request.model||t('inheritCodexConfig')))}${settingsSummaryRow(t('reasoningEffort'),escapeHTML(request.reasoningEffort||t('inheritCodexConfig')))}${settingsSummaryRow(t('totalTokens'),tokenNumber(request.totalTokens))}${settingsSummaryRow(t('inputTokens'),tokenNumber(request.inputTokens))}${settingsSummaryRow(t('cachedInputTokens'),tokenNumber(request.cachedInputTokens))}${settingsSummaryRow(t('outputTokens'),tokenNumber(request.outputTokens))}${settingsSummaryRow(t('reasoningTokens'),tokenNumber(request.reasoningTokens))}</dl>`:'';openDrawer(request.id,`<section class="agent-request-detail"><header><span>${badge(request.status,request.status==='succeeded'?'signal':request.status==='failed'?'danger':'')}</span><h3>${escapeHTML(request.title)}</h3><p>${escapeHTML(requestKindLabel[request.kind]||request.kind)}${request.sourceWorkItemId?` · ${escapeHTML(request.sourceWorkItemId)}`:''}</p></header>${runtime}<article><h4>${t('outcome')}</h4><pre>${escapeHTML(result||'—')}</pre></article>${request.outputJsonl?`<details><summary>${t('rawLog')}</summary><pre>${escapeHTML(request.outputJsonl)}</pre></details>`:''}<div class="drawer-actions">${actions}</div></section>`,()=>{$('#approvePlan')?.addEventListener('click',async()=>{await api(`/api/agent-requests/${id}/approve-plan`,{method:'POST',body:'{}'});closeDrawer();toast(t('requestCreated'));renderAgentRequests()});$('#retryRequest')?.addEventListener('click',async()=>{await api(`/api/agent-requests/${id}/retry`,{method:'POST',body:'{}'});closeDrawer();toast(t('requestCreated'));renderAgentRequests()});$('#cancelRequest')?.addEventListener('click',async()=>{await api(`/api/agent-requests/${id}/cancel`,{method:'POST',body:'{}'});closeDrawer();renderAgentRequests()})})};
